    # ── git hook 转发端到端 ──
    {"id": "run-tests.sh:2128", "line": 2128, "kind": "t", "desc": "合法 message 经 hook 提交成功", "prelude": [{"kind": "chunk", "line": 2107, "text": "\necho \"== git hook 转发端到端 ==\""}, {"kind": "new_repo", "line": 2109}, {"kind": "chunk", "line": 2110, "text": "wfile docs/tickets/0002-hook-ticket.md <<'EOF'\n---\nid: 0002\ntype: feature\nspec: 0001\nstatus: in-progress\nblocked-by: []\ncreated: 2026-10-28\n---\n# 0002: hook 端到端工单\n\n## Progress\n- 测试夹具。\nEOF\nprintf '#!/bin/sh\\n# sdlc-managed: forward\\nexec \"$(git rev-parse --show-toplevel)/.sdlc/check.sh\" commit-msg \"$@\"\\n' > \"$TMP/.git/hooks/commit-msg\"\nchmod +x \"$TMP/.git/hooks/commit-msg\"\nprintf 'y\\n' > \"$TMP/f.txt\"\ngit -C \"$TMP\" add f.txt"}], "want": 0, "cmd": "git -C $TMP commit -qm '[#0002] via hook'", "cmd_raw": "\"git -C $TMP commit -qm '[#0002] via hook'\"", "substr": ""},
