    {"id": "run-tests.sh:2230", "line": 2230, "kind": "t", "desc": "sdlc-managed 重装后转发仍生效", "prelude": [{"kind": "chunk", "line": 2228, "text": "install_member_hook             # 幂等重装：同模板整体覆盖\necho nine > \"$TMP/frontend/i.txt\"; git -C \"$TMP/frontend\" add i.txt"}], "want": 0, "cmd": "git -C $TMP/frontend commit -qm '[#0002] z'", "cmd_raw": "\"git -C $TMP/frontend commit -qm '[#0002] z'\"", "substr": "门禁通过"},
    {"id": "run-tests.sh:2231", "line": 2231, "kind": "t", "desc": "成员 hook 带 sdlc-managed 标记（幂等判定依据）", "prelude": [], "want": 0, "cmd": "grep -q sdlc-managed $TMP/frontend/.git/hooks/commit-msg", "cmd_raw": "\"grep -q sdlc-managed $TMP/frontend/.git/hooks/commit-msg\"", "substr": ""},
    {"id": "run-tests.sh:2232", "line": 2232, "kind": "t", "desc": "成员未装 pre-push（need C3）", "prelude": [], "want": 0, "cmd": "test ! -f $TMP/frontend/.git/hooks/pre-push", "cmd_raw": "\"test ! -f $TMP/frontend/.git/hooks/pre-push\"", "substr": ""},
    # ── 成员门禁转发成文契约（generation.md 多仓节 / SKILL §3 行） ──
    {"id": "run-tests.sh:2239", "line": 2239, "kind": "oseq", "desc": "成员 hook 细则按序成文：一行转发、不装 pre-push、消息文件绝对路径、锚定工作区仓库根、自定位错位理由、外来 hook 沿用不覆盖", "prelude": [{"kind": "chunk", "line": 2233, "text": "\necho \"== 成员门禁转发成文契约（generation.md 多仓节 / SKILL §3 行）==\"\nGEN=\"$HERE/../references/generation.md\"\nSKILL=\"$HERE/../../setup-workspace/SKILL.md\"\nmkdir -p \"$TMP/txt\"\nawk '/^### 多仓工作区模式/{f=1;next} /^## 2\\. /{f=0} f' \"$GEN\" > \"$TMP/txt/multi.md\""}], "file": "$TMP/txt/multi.md", "words": ["commit-msg", "不装 pre-push", "成员仓库", "自定位", "锚定", "外来 hook", "不覆盖"]},
    {"id": "run-tests.sh:2240", "line": 2240, "kind": "t", "desc": "成员转发模板落文（sdlc-managed 标记 + dirname 锚定 + exec check.sh commit-msg）", "prelude": [], "want": 0, "cmd": "grep -q 'sdlc-managed: forward to workspace root' \"$TMP/txt/multi.md\" && grep -q 'dirname' \"$TMP/txt/multi.md\" && grep -q 'exec ./.sdlc/check.sh commit-msg' \"$TMP/txt/multi.md\"", "cmd_raw": "\"grep -q 'sdlc-managed: forward to workspace root' \\\"$TMP/txt/multi.md\\\" && grep -q 'dirname' \\\"$TMP/txt/multi.md\\\" && grep -q 'exec ./.sdlc/check.sh commit-msg' \\\"$TMP/txt/multi.md\\\"\"", "substr": ""},
    {"id": "run-tests.sh:2241", "line": 2241, "kind": "t", "desc": "SKILL §3 增成员 hook 行（仅多仓工作区模式、不装 pre-push、外来 hook 处置同根）", "prelude": [], "want": 0, "cmd": "grep -q '成员 `.git/hooks/commit-msg`（仅多仓' \"$SKILL\" && grep -q '不装 pre-push' \"$SKILL\" && grep -q '外来 hook 处置同根' \"$SKILL\"", "cmd_raw": "\"grep -q '成员 \\`.git/hooks/commit-msg\\`（仅多仓' \\\"$SKILL\\\" && grep -q '不装 pre-push' \\\"$SKILL\\\" && grep -q '外来 hook 处置同根' \\\"$SKILL\\\"\"", "substr": ""},
    # ── 多仓工作区成员哨兵块（FR-6 三态） ──
    {"id": "run-tests.sh:2271", "line": 2271, "kind": "t", "desc": "成员无 AGENTS.md：创建并落成员版哨兵块标记", "prelude": [{"kind": "chunk", "line": 2242, "text": "\necho \"== 多仓工作区成员哨兵块（FR-6 三态）==\"\n# 成员哨兵固定文本直接从 generation.md「成员 AGENTS.md 哨兵块」小节提取并替换\n# <成员目录名> 占位——夹具落装的就是文档原文，固定文本与文档不可能漂移；\n# 三态规则（不存在→创建 / 无标记→文末追加 / 有标记→块内替换）照细则机械复现\nmember_sentinel_text() {\n  awk '/^### 成员 AGENTS.md 哨兵块/{f=1;next} /^## [0-9]|^### /{f=0} f' \"$GEN\" \\\n    | awk '/^```/{f=!f;next} f' | sed \"s/<成员目录名>/$1/g\"\n}\napply_member_sentinel() { # $1 成员目录名 [$2 工作区根，缺省 $TMP]：三态落成员版哨兵块\n  local body f root\n  root=\"${2:-$TMP}\"\n  body=\"$(member_sentinel_text \"$1\")\"\n  f=\"$root/$1/AGENTS.md\"\n  if [ ! -f \"$f\" ]; then\n    printf '# AGENTS.md\\n\\n%s\\n' \"$body\" > \"$f\"\n  elif ! grep -q '<!-- sdlc:begin' \"$f\"; then\n    printf '\\n%s\\n' \"$body\" >> \"$f\"\n  else\n    # awk -v 会把值里的换行当转义错处理，多行文本经 ENVIRON 原样传入\n    MEMBER_SENTINEL_REPL=\"$body\" awk '\n      /<!-- sdlc:begin/ { print ENVIRON[\"MEMBER_SENTINEL_REPL\"]; inblk=1; next }\n      inblk { if (/<!-- sdlc:end -->/) inblk=0; next }\n      { print }\n    ' \"$f\" > \"$f.new\" && mv \"$f.new\" \"$f\"\n  fi\n}\nrm -f \"$TMP/frontend/AGENTS.md\"\napply_member_sentinel frontend"}], "want": 0, "cmd": "grep -q '<!-- sdlc:begin' \"$TMP/frontend/AGENTS.md\" && grep -q '<!-- sdlc:end -->' \"$TMP/frontend/AGENTS.md\"", "cmd_raw": "\"grep -q '<!-- sdlc:begin' \\\"$TMP/frontend/AGENTS.md\\\" && grep -q '<!-- sdlc:end -->' \\\"$TMP/frontend/AGENTS.md\\\"\"", "substr": ""},
    {"id": "run-tests.sh:2272", "line": 2272, "kind": "t", "desc": "成员创建态带一级标题", "prelude": [], "want": 0, "cmd": "head -n 1 \"$TMP/frontend/AGENTS.md\" | grep -qx '# AGENTS.md'", "cmd_raw": "\"head -n 1 \\\"$TMP/frontend/AGENTS.md\\\" | grep -qx '# AGENTS.md'\"", "substr": ""},
    {"id": "run-tests.sh:2273", "line": 2273, "kind": "oseq", "desc": "成员哨兵三要素按序成文：成员身份、工作区根指引、流程回根、代码照常", "prelude": [], "file": "$TMP/frontend/AGENTS.md", "words": ["成员子仓库", "工作区仓库在上级目录", "回工作区根进行", "照常进行"]},
    {"id": "run-tests.sh:2278", "line": 2278, "kind": "t", "desc": "成员 AGENTS.md 无标记：文末追加哨兵块", "prelude": [{"kind": "chunk", "line": 2274, "text": "mkdir -p \"$TMP/backend\"\nprintf '# 后端仓库说明\\n\\n包管理器用 pnpm。\\n' > \"$TMP/backend/AGENTS.md\"\ncp \"$TMP/backend/AGENTS.md\" \"$TMP/backend-agents.before\"\napply_member_sentinel backend"}], "want": 0, "cmd": "grep -q '<!-- sdlc:begin' \"$TMP/backend/AGENTS.md\" && tail -n 1 \"$TMP/backend/AGENTS.md\" | grep -q '<!-- sdlc:end -->'", "cmd_raw": "\"grep -q '<!-- sdlc:begin' \\\"$TMP/backend/AGENTS.md\\\" && tail -n 1 \\\"$TMP/backend/AGENTS.md\\\" | grep -q '<!-- sdlc:end -->'\"", "substr": ""},
