    {"id": "run-tests.sh:2413", "line": 2413, "kind": "t", "desc": "gateway 提交引用 in-progress 工单放行（补装门禁即刻生效）", "prelude": [{"kind": "chunk", "line": 2412, "text": "echo gw2 > \"$TMP/gateway/gw2.txt\"; git -C \"$TMP/gateway\" add gw2.txt"}], "want": 0, "cmd": "git -C $TMP/gateway commit -qm '[#0002] gateway in'", "cmd_raw": "\"git -C $TMP/gateway commit -qm '[#0002] gateway in'\"", "substr": "门禁通过"},
    {"id": "run-tests.sh:2415", "line": 2415, "kind": "t", "desc": "gateway 无引用非豁免提交同样被拦（与初始成员同规）", "prelude": [{"kind": "chunk", "line": 2414, "text": "echo gw3 > \"$TMP/gateway/gw3.txt\"; git -C \"$TMP/gateway\" add gw3.txt"}], "want": 1, "cmd": "git -C $TMP/gateway commit -qm 'no tag'", "cmd_raw": "\"git -C $TMP/gateway commit -qm 'no tag'\"", "substr": "[#NNNN]"},
    {"id": "run-tests.sh:2416", "line": 2416, "kind": "t", "desc": "标记段同步 gateway/ 且 begin/end 恰一对", "prelude": [], "want": 0, "cmd": "[ \"$(grep -c '^# sdlc:members' \"$TMP/.gitignore\")\" = 2 ] && grep -qx 'gateway/' \"$TMP/.gitignore\"", "cmd_raw": "\"[ \\\"\\$(grep -c '^# sdlc:members' \\\"$TMP/.gitignore\\\")\\\" = 2 ] && grep -qx 'gateway/' \\\"$TMP/.gitignore\\\"\"", "substr": ""},
    {"id": "run-tests.sh:2417", "line": 2417, "kind": "t", "desc": "用户自有行跨重写保留（*.log 仍在段外首行）", "prelude": [], "want": 0, "cmd": "head -n 1 \"$TMP/.gitignore\" | grep -qx '*.log'", "cmd_raw": "\"head -n 1 \\\"$TMP/.gitignore\\\" | grep -qx '*.log'\"", "substr": ""},
    {"id": "run-tests.sh:2423", "line": 2423, "kind": "t", "desc": "重跑求差：消失成员 backend 被点名报缺失", "prelude": [{"kind": "chunk", "line": 2418, "text": "\necho \"-- 幕二：成员目录消失 → 报告缺失、未确认前清单不动、确认后才移出 --\"\nrm -rf \"$TMP/backend\"\ncp \"$TMP/.sdlc/members.list\" \"$TMP/manifest.before\"\ncp \"$TMP/.gitignore\" \"$TMP/gitignore.before\""}], "want": 0, "cmd": "[ \"$(mdiff_missing \"$TMP\")\" = backend ]", "cmd_raw": "\"[ \\\"\\$(mdiff_missing \\\"$TMP\\\")\\\" = backend ]\"", "substr": ""},
