    {"id": "run-tests.sh:2426", "line": 2426, "kind": "t", "desc": "未确认前 .gitignore 一字不动（backend/ 仍在段内）", "prelude": [], "want": 0, "cmd": "diff \"$TMP/gitignore.before\" \"$TMP/.gitignore\" && grep -qx 'backend/' \"$TMP/.gitignore\"", "cmd_raw": "\"diff \\\"$TMP/gitignore.before\\\" \\\"$TMP/.gitignore\\\" && grep -qx 'backend/' \\\"$TMP/.gitignore\\\"\"", "substr": ""},
    {"id": "run-tests.sh:2430", "line": 2430, "kind": "t", "desc": "确认后清单移出 backend（frontend/gateway 各一行）", "prelude": [{"kind": "chunk", "line": 2427, "text": "# 用户显式确认移出 → 清单与标记段整体重写\nmscan \"$TMP\" > \"$TMP/.sdlc/members.list\"\nms_rewrite_members_gitignore \"$TMP\""}], "want": 0, "cmd": "printf 'frontend\\ngateway\\n' | diff - .sdlc/members.list", "cmd_raw": "\"printf 'frontend\\ngateway\\n' | diff - .sdlc/members.list\"", "substr": ""},
