    # ── 复原幕：新环境 clone 根仓与成员后重跑零询问（FR-8） ──
    {"id": "run-tests.sh:2502", "line": 2502, "kind": "t", "desc": "克隆根自带 check.sh 与成员清单（清单命中即复原前提）", "prelude": [{"kind": "chunk", "line": 2454, "text": "\necho \"== 复原幕：新环境 clone 根仓与成员后重跑零询问（FR-8）==\"\n# 原型工作区装满后整体提交，clone 出\"新环境\"：根仓自带 .sdlc/docs/成员清单，成员哨兵\n# 随提交走，hooks 不随 clone 传递——重跑的幂等重装是刚需而非摆设。清单命中成员视为\n# 已确认（决策 4 复原零询问），求差零新增零缺失即零询问的机械前提。"}, {"kind": "new_repo", "line": 2459}, {"kind": "chunk", "line": 2460, "text": "mkdir -p \"$TMP/frontend\" \"$TMP/backend\"\nfor m in frontend backend; do\n  git -C \"$TMP/$m\" init -q -b main\n  git -C \"$TMP/$m\" config user.email test@example.com\n  git -C \"$TMP/$m\" config user.name tester\n  echo base > \"$TMP/$m/base.txt\"\n  git -C \"$TMP/$m\" add base.txt\n  git -C \"$TMP/$m\" commit -qm init\ndone\nwfile docs/tickets/0002-restore-gate.md <<'EOF'\n---\nid: 0002\ntype: feature\nspec: 0001\nstatus: in-progress\nblocked-by: []\ncreated: 2026-10-29\n---\n# 0002: 复原幕夹具工单\n\n## Progress\n- 夹具\nEOF\nmscan \"$TMP\" > \"$TMP/.sdlc/members.list\"\n{\n  printf '*.log\\n\\n'\n  printf '%s\\n' \"$ms_begin\"\n  sed 's#$#/#' \"$TMP/.sdlc/members.list\"\n  printf '%s\\n' \"$ms_end\"\n} > \"$TMP/.gitignore\"\ninstall_member_hook \"$TMP/frontend\"\ninstall_member_hook \"$TMP/backend\"\napply_member_sentinel frontend\napply_member_sentinel backend\ngit -C \"$TMP\" add .sdlc docs .gitignore\ngit -C \"$TMP\" commit -qm \"[trivial] 工作区原型\"\ngit -C \"$TMP/frontend\" add AGENTS.md && git -C \"$TMP/frontend\" commit -qm \"[trivial] sentinel\"\ngit -C \"$TMP/backend\" add AGENTS.md && git -C \"$TMP/backend\" commit -qm \"[trivial] sentinel\"\nRESTORE=\"$TMP/restore\"\ngit clone -q \"$TMP\" \"$RESTORE\"\ngit clone -q \"$TMP/frontend\" \"$RESTORE/frontend\"\ngit clone -q \"$TMP/backend\" \"$RESTORE/backend\""}], "want": 0, "cmd": "test -x \"$RESTORE/.sdlc/check.sh\" && grep -q frontend \"$RESTORE/.sdlc/members.list\"", "cmd_raw": "\"test -x \\\"$RESTORE/.sdlc/check.sh\\\" && grep -q frontend \\\"$RESTORE/.sdlc/members.list\\\"\"", "substr": ""},
    {"id": "run-tests.sh:2503", "line": 2503, "kind": "t", "desc": "克隆起点：根与成员均无 sdlc hook（hooks 不随 clone 传递，重装是刚需）", "prelude": [], "want": 0, "cmd": "test ! -f \"$RESTORE/.git/hooks/commit-msg\" && test ! -f \"$RESTORE/frontend/.git/hooks/commit-msg\" && test ! -f \"$RESTORE/backend/.git/hooks/commit-msg\"", "cmd_raw": "\"test ! -f \\\"$RESTORE/.git/hooks/commit-msg\\\" && test ! -f \\\"$RESTORE/frontend/.git/hooks/commit-msg\\\" && test ! -f \\\"$RESTORE/backend/.git/hooks/commit-msg\\\"\"", "substr": ""},
    {"id": "run-tests.sh:2504", "line": 2504, "kind": "t", "desc": "复原求差：零新增零缺失——全程零重复询问的机械前提", "prelude": [], "want": 0, "cmd": "[ -z \"$(mdiff_new \"$RESTORE\")\" ] && [ -z \"$(mdiff_missing \"$RESTORE\")\" ]", "cmd_raw": "\"[ -z \\\"\\$(mdiff_new \\\"$RESTORE\\\")\\\" ] && [ -z \\\"\\$(mdiff_missing \\\"$RESTORE\\\")\\\" ]\"", "substr": ""},
    {"id": "run-tests.sh:2513", "line": 2513, "kind": "t", "desc": "重装后成员提交过门禁：工单随根 clone 而来，ROOT 锚定复原根", "prelude": [{"kind": "chunk", "line": 2505, "text": "# 清单命中成员视为已确认（决策 4 复原零询问）：直接幂等重装，无任何确认交互\ninstall_member_hook \"$RESTORE/frontend\"\ninstall_member_hook \"$RESTORE/backend\"\napply_member_sentinel frontend \"$RESTORE\"\napply_member_sentinel backend \"$RESTORE\"\nprintf '#!/bin/sh\\n# sdlc-managed: forward\\nexec \"$(git rev-parse --show-toplevel)/.sdlc/check.sh\" commit-msg \"$@\"\\n' > \"$RESTORE/.git/hooks/commit-msg\"\nchmod +x \"$RESTORE/.git/hooks/commit-msg\"\necho r > \"$RESTORE/frontend/restored.txt\"; git -C \"$RESTORE/frontend\" add restored.txt"}], "want": 0, "cmd": "git -C $RESTORE/frontend commit -qm '[#0002] restored'", "cmd_raw": "\"git -C $RESTORE/frontend commit -qm '[#0002] restored'\"", "substr": "门禁通过"},
    {"id": "run-tests.sh:2514", "line": 2514, "kind": "t", "desc": "复原哨兵幂等：克隆携带的 AGENTS.md 重装零变化", "prelude": [], "want": 0, "cmd": "cmp \"$TMP/frontend/AGENTS.md\" \"$RESTORE/frontend/AGENTS.md\"", "cmd_raw": "\"cmp \\\"$TMP/frontend/AGENTS.md\\\" \\\"$RESTORE/frontend/AGENTS.md\\\"\"", "substr": ""},
    {"id": "run-tests.sh:2515", "line": 2515, "kind": "t", "desc": "复原根自身提交过自身转发 hook", "prelude": [], "want": 0, "cmd": "git -C $RESTORE commit -q --allow-empty -m '[trivial] restore probe'", "cmd_raw": "\"git -C $RESTORE commit -q --allow-empty -m '[trivial] restore probe'\"", "substr": "豁免"},
    {"id": "run-tests.sh:2516", "line": 2516, "kind": "t", "desc": "check.sh phase 正常输出（FR-8 自检：clone 来的工单可见）", "prelude": [], "want": 0, "cmd": "cd \"$RESTORE\" && ./.sdlc/check.sh phase", "cmd_raw": "\"cd \\\"$RESTORE\\\" && ./.sdlc/check.sh phase\"", "substr": "0002-restore-gate"},
    # ── 过程档 gitignore 行为（seam 1） ──
    {"id": "run-tests.sh:2563", "line": 2563, "kind": "tn", "desc": "过程档新建票不进 git status", "prelude": [{"kind": "chunk", "line": 2517, "text": "\necho \"== 过程档 gitignore 行为（seam 1）==\""}, {"kind": "new_repo", "line": 2519}, {"kind": "chunk", "line": 2520, "text": "printf 'docs/tickets/\\ndocs/reviews/\\ndocs/acceptance/\\n' >> \"$TMP/.gitignore\"\n# check-ignore 的目录级模式（尾斜杠）只命中磁盘上真实存在的目录，空目录也要先建出来\nmkdir -p \"$TMP/docs/reviews\" \"$TMP/docs/acceptance\"\n# 真实仓库中 docs/ 知识档是被跟踪的：先入库一张知识档做基线，\n# 否则整个 docs/ 未跟踪会被 status 折叠为 `?? docs/`，两层行为都观测不到\nwfile docs/needs/0001-tier-contrast.md <<'EOF'\n---\nid: 0001\nstatus: confirmed\ncreated: 2026-10-29\n---\n# 忽略行为对照 need\n\n## 背景与业务目标\n测试夹具。\nEOF\ngit -C \"$TMP\" add docs/needs/0001-tier-contrast.md\ngit -C \"$TMP\" commit -qm \"[trivial] fixture 知识档进库基线\"\nwfile docs/needs/0002-tier-contrast-new.md <<'EOF'\n---\nid: 0002\nstatus: draft\ncreated: 2026-10-29\n---\n# 忽略行为对照 need（新建）\n\n## 背景与业务目标\n测试夹具。\nEOF\nwfile docs/tickets/0001-swept-ticket.md <<'EOF'\n---\nid: 0001\ntype: feature\nspec: 0001\nstatus: in-progress\nblocked-by: []\ncreated: 2026-10-29\n---\n# 0001: 过程档忽略行为夹具工单\n\n## Progress\n- 测试夹具。\nEOF"}], "want": 0, "cmd": "git status --porcelain", "cmd_raw": "\"git status --porcelain\"", "absent": "docs/tickets"},
