    {"id": "run-tests.sh:3017", "line": 3017, "kind": "t", "desc": "候选号占位已存在时重掷随机段返回新号（FR-2 撞号重试）", "prelude": [{"kind": "chunk", "line": 3000, "text": "fake_cmd od <<'EOF'\n#!/bin/sh\n# 测试替身 od：从 CLAIM_OD_SEQ 逐行弹出随机段；耗尽后恒输出 dead\nseqfile=\"${CLAIM_OD_SEQ:-}\"\nif [ -n \"$seqfile\" ] && [ -f \"$seqfile\" ]; then\n  n=\"$(sed -n '1p' \"$seqfile\")\"\n  if [ -n \"$n\" ]; then\n    sed -i.bak 1d \"$seqfile\" && rm -f \"$seqfile.bak\"\n    printf '%s\\n' \"$n\"\n    exit 0\n  fi\nfi\nprintf 'dead\\n'\nEOF\nmkdir -p \"$TMP/docs/tickets\"\n: > \"$TMP/docs/tickets/$(date +%Y%m%d)-b7c1-parked-slug.md\"\nprintf 'b7c1\\na1f2\\n' > \"$TMP/odseq\""}], "want": 0, "cmd": "CLAIM_OD_SEQ=\"$TMP/odseq\" PATH=\"$TMP/fakebin:$PATH\" check.sh claim ticket parked-slug | grep -qE '^docs/tickets/[0-9]{8}-a1f2-parked-slug\\.md$'", "cmd_raw": "\"CLAIM_OD_SEQ=\\\"$TMP/odseq\\\" PATH=\\\"$TMP/fakebin:\\$PATH\\\" check.sh claim ticket parked-slug | grep -qE '^docs/tickets/[0-9]{8}-a1f2-parked-slug\\\\.md\\$'\"", "substr": ""},
